export class Common{constructor(){this.reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches,this.revealTargets=document.querySelectorAll(".reveal"),this.statNumbers=document.querySelectorAll(".stat-number[data-count-to]"),this.flavorSliders=document.querySelectorAll(".flavor-photo--slider"),this.heroVisual=document.getElementById("heroVisual"),this.heroPastilaImg=document.getElementById("heroPastilaImg"),this.init()}init(){this.initReveal(),this.initCounters(),this.initFlavorSliders(),this.initHeroParallax()}initReveal(){if(this.reduceMotion||!this.revealTargets.length||!("IntersectionObserver"in window))return void this.revealTargets.forEach(e=>e.classList.add("is-visible"));const e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("is-visible"),e.unobserve(t.target))})},{threshold:.15});this.revealTargets.forEach(t=>e.observe(t))}initCounters(){if(!this.statNumbers.length)return;const e=this.reduceMotion;if(!e&&"IntersectionObserver"in window){const t=new IntersectionObserver(r=>{r.forEach(r=>{r.isIntersecting&&((t=>{const r=parseInt(t.getAttribute("data-count-to"),10);if(e||!("IntersectionObserver"in window))return void(t.textContent=r);let i=null;const s=e=>{null===i&&(i=e);const o=Math.min((e-i)/800,1);t.textContent=Math.floor(o*r),o<1?window.requestAnimationFrame(s):t.textContent=r};window.requestAnimationFrame(s)})(r.target),t.unobserve(r.target))})},{threshold:.5});this.statNumbers.forEach(e=>t.observe(e))}else this.statNumbers.forEach(e=>{e.textContent=e.getAttribute("data-count-to")})}initFlavorSliders(){this.flavorSliders.forEach(e=>{const t=e.querySelectorAll(".fp-slide"),r=e.querySelectorAll(".fp-dot"),i=e.querySelector(".fp-arrow--prev"),s=e.querySelector(".fp-arrow--next");let o=0;const n=e=>{o=(e+t.length)%t.length,t.forEach((e,t)=>e.classList.toggle("is-active",t===o)),r.forEach((e,t)=>e.classList.toggle("is-active",t===o))};r.forEach((e,t)=>{e.addEventListener("click",e=>{e.preventDefault(),n(t)})}),i&&i.addEventListener("click",e=>{e.preventDefault(),n(o-1)}),s&&s.addEventListener("click",e=>{e.preventDefault(),n(o+1)})})}initHeroParallax(){!this.reduceMotion&&this.heroVisual&&this.heroPastilaImg&&window.matchMedia("(hover: hover)").matches&&(this.heroVisual.addEventListener("mousemove",e=>{const t=this.heroVisual.getBoundingClientRect(),r=(e.clientX-t.left)/t.width-.5,i=(e.clientY-t.top)/t.height-.5;this.heroPastilaImg.style.transform="translate("+-18*r+"px,"+-14*i+"px)"}),this.heroVisual.addEventListener("mouseleave",()=>{this.heroPastilaImg.style.transform=""}))}}